TYPE E_P11_State :
(
    P11_IDLE := 0,
    P11_MOVE_A_B,
    P11_WAIT_B,
    P11_MOVE_B_C,
    P11_WAIT_C,
    P11_DONE
);
END_TYPE

FUNCTION_BLOCK FB_P11
VAR_INPUT
    Mode : BOOL;
    ForwardButton : BOOL;
    ReverseButton : BOOL;
    SensorA : BOOL;
    SensorB : BOOL;
    SensorC : BOOL;
    ButtonA : BOOL;
    ButtonB : BOOL;
    ButtonC : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward : BOOL;
    MotorReverse : BOOL;
    CompletionLight : BOOL;
END_VAR
VAR
    FirstScan : BOOL := TRUE;
    State : E_P11_State := P11_IDLE;
    ButtonA_R : R_TRIG;
    ButtonB_R : R_TRIG;
    ButtonC_R : R_TRIG;
END_VAR

ButtonA_R(CLK := ButtonA);
ButtonB_R(CLK := ButtonB);
ButtonC_R(CLK := ButtonC);

IF FirstScan THEN
    MotorForward := FALSE;
    MotorReverse := FALSE;
    CompletionLight := FALSE;
    State := P11_IDLE;
    FirstScan := FALSE;
ELSE
    IF Mode THEN
        (* 自动模式：A -> B -> C 顺序推进 *)
        MotorForward := FALSE;
        MotorReverse := FALSE;

        CASE State OF
            P11_IDLE:
                IF SensorA AND ButtonA_R.Q THEN
                    State := P11_MOVE_A_B;
                    MotorForward := TRUE;
                END_IF;

            P11_MOVE_A_B:
                MotorForward := TRUE;
                IF SensorB THEN
                    MotorForward := FALSE;
                    State := P11_WAIT_B;
                END_IF;

            P11_WAIT_B:
                MotorForward := FALSE;
                IF SensorB AND ButtonB_R.Q THEN
                    State := P11_MOVE_B_C;
                    MotorForward := TRUE;
                END_IF;

            P11_MOVE_B_C:
                MotorForward := TRUE;
                IF SensorC THEN
                    MotorForward := FALSE;
                    State := P11_WAIT_C;
                END_IF;

            P11_WAIT_C:
                MotorForward := FALSE;
                IF SensorC AND ButtonC_R.Q THEN
                    CompletionLight := TRUE;
                    State := P11_DONE;
                END_IF;

            P11_DONE:
                MotorForward := FALSE;
                IF NOT SensorC THEN
                    CompletionLight := FALSE;
                    State := P11_IDLE;
                END_IF;
        END_CASE;
    ELSE
        (* 手动模式：正反转按钮控制，并互锁 *)
        MotorForward := ForwardButton AND NOT ReverseButton;
        MotorReverse := ReverseButton AND NOT ForwardButton;

        IF NOT SensorC THEN
            CompletionLight := FALSE;
        END_IF;
    END_IF;

    (* 完成灯约束：灯亮必须在 C 站到位；离开 C 站后熄灭 *)
    IF NOT SensorC THEN
        CompletionLight := FALSE;
        IF (State = P11_DONE) OR (State = P11_WAIT_C) THEN
            State := P11_IDLE;
        END_IF;
    END_IF;

    (* 硬互锁：正转与反转不得同时输出 *)
    IF MotorForward AND MotorReverse THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
